  const iconAtlas=new Map();
  function icon(type){if(iconAtlas.has(type))return iconAtlas.get(type);const c=document.createElement('canvas');c.width=108;c.height=108;const q=c.getContext('2d');q.scale(3,3);q.translate(18,18);drawItem(q,type);iconAtlas.set(type,c);return c;}
  function itemIcon(type,x,y,s=1){g.save();g.translate(x,y);g.scale(s,s);g.imageSmoothingEnabled=true;g.drawImage(icon(type),-18,-18,36,36);g.restore();}
  function keyIcon(x,y,s=1){itemIcon('key',x,y,s);}
  function brick(q,x,y,cave=false){const t=theme(),seed=((x*17+y*11)%29)/29;box(q,x,y,16,16,t.seam);if(cave){path(q,gradient(q,x,y,13,15,t.stone,t.shade),t.seam,p=>{p.moveTo(x+1,y+2);p.lineTo(x+10,y+1);p.lineTo(x+15,y+6);p.lineTo(x+13,y+15);p.lineTo(x+3,y+15);p.lineTo(x+1,y+10);p.closePath();},.8);line(q,[[x+3,y+3],[x+10,y+2],[x+13,y+6]],t.edge,.65);}else{box(q,x+.7,y+.6,14.6,14.5,gradient(q,x,y,0,16,t.stone,t.shade),1.2,t.seam,.5);line(q,[[x+2,y+12],[x+2,y+2],[x+13,y+2]],t.edge,.7);line(q,[[x+5,y+14],[x+14,y+14],[x+14,y+5]],t.seam,.7);}if(seed>.64)line(q,[[x+8,y+5],[x+6,y+8],[x+8,y+10]],t.shade,.55);}
  function arch(q,x,y,w,h,fill,stroke,lw=1){path(q,fill,stroke,p=>{p.moveTo(x,y+h);p.lineTo(x,y+w/2);p.arc(x+w/2,y+w/2,w/2,Math.PI,Math.PI*2);p.lineTo(x+w,y+h);p.closePath();},lw);}
  function windowArt(q,x,y,w=24,h=37){const t=theme();arch(q,x-2,y-2,w+4,h+4,t.shade,t.seam,1);arch(q,x,y,w,h,gradient(q,x,y,0,h,'#15223d','#628aa0'),t.edge,.8);q.save();arch(q,x+1,y+1,w-2,h-2);q.clip();ellipse(q,x+w*.68,y+10,5,5,'#f6e4ab');for(let i=0;i<5;i++)ellipse(q,x+3+(i*7%19),y+6+(i*11%23),.5,.5,'#d9e6d4');path(q,'#274758',null,p=>{p.moveTo(x,y+h);p.lineTo(x,y+h-8);p.lineTo(x+5,y+h-8);p.lineTo(x+5,y+h-15);p.lineTo(x+10,y+h-18);p.lineTo(x+15,y+h-15);p.lineTo(x+15,y+h-8);p.lineTo(x+w,y+h-10);p.lineTo(x+w,y+h);p.closePath();});q.restore();line(q,[[x+w/2,y+2],[x+w/2,y+h]],t.shade,1.5);line(q,[[x+2,y+h*.58],[x+w-2,y+h*.58]],t.shade,1.2);box(q,x-3,y+h,w+6,3,t.edge,1);}
